// Turns the reviewed legal texts in docs/legal/*.md into a TypeScript module the app can import
// (Workers have no filesystem, so the markdown cannot be read at runtime).
//   node scripts/legal/sync.mjs          writes src/content/legal/generated.ts
//   node scripts/legal/sync.mjs --check  exits 1 if the generated file is out of date
// docs/legal/*.md stays the single source of truth: edit there, then run `pnpm legal:sync`.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "../..");
const read = (name) => readFileSync(join(root, "docs/legal", name), "utf8").replace(/\r\n/g, "\n");

/** Text between a "## X." heading and the next "## " heading or "---" rule. */
function section(markdown, heading) {
  const start = markdown.indexOf(`\n## ${heading}`);
  if (start === -1) throw new Error(`Section "${heading}" not found`);
  const bodyStart = markdown.indexOf("\n", start + 1) + 1;
  const rest = markdown.slice(bodyStart);
  const end = rest.search(/\n(?:## |---\n)/);
  return (end === -1 ? rest : rest.slice(0, end)).trim();
}

export function build() {
  const owners = read("aviso-privacidad-duenos.md");
  const clients = read("aviso-privacidad-clientes.md");
  const terms = read("terminos-duenos.md");

  const version = /Versión:\s*`([^`]+)`/.exec(terms)?.[1];
  if (!version) throw new Error('terminos-duenos.md must declare "Versión: `x.y`"');

  // The short notice is the blockquote under "## A."; the page shows B (integral) and C (conditions).
  const shortBlock = section(clients, "A. Versión corta (se muestra en el formulario de reserva, junto al botón \"Confirmar cita\")");
  const short = shortBlock
    .split("\n")
    .filter((line) => line.startsWith(">"))
    .map((line) => line.replace(/^>\s?/, ""))
    .join(" ")
    .trim();

  const docs = {
    version,
    privacyOwners: owners.trim(),
    terms: terms.trim(),
    privacyClientsShort: short,
    privacyClientsFull: `${section(clients, "B. Versión integral")}\n\n## Condiciones de la reserva\n\n${section(clients, "C. Condiciones de la reserva (texto breve para la página de la cita o pie del perfil)")}`.trim(),
  };

  return (
    "// AUTO-GENERATED by scripts/legal/sync.mjs from docs/legal/*.md. Do not edit by hand: edit the markdown and run `pnpm legal:sync`.\n" +
    Object.entries(docs)
      .map(([key, value]) => `export const ${key} = ${JSON.stringify(value)};\n`)
      .join("")
  );
}

const target = join(root, "src/content/legal/generated.ts");
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const output = build();
  if (process.argv.includes("--check")) {
    const current = (() => {
      try {
        return readFileSync(target, "utf8");
      } catch {
        return "";
      }
    })();
    if (current !== output) {
      console.error("src/content/legal/generated.ts is out of date. Run `pnpm legal:sync`.");
      process.exit(1);
    }
  } else {
    writeFileSync(target, output);
    console.log("wrote src/content/legal/generated.ts");
  }
}
